-- migration_029_new_questions_oct2026b.sql
-- Batch 14 of new questions from "questions to add.pdf" (Psychology):
--   q_sba_motivational_interviewing_opioid_001 (SBA) -- new knowledge box "Motivational
--     Interviewing" (spirit per Miller and Rollnick 2013: partnership, acceptance, compassion,
--     evocation) + new images/motivational-interviewing-oars.svg (spirit, OARS, four processes); no change-talk content
--   q_emq_psychological_approaches_001 (EMQ) -- new knowledge box "Psychological Approaches in
--     Pain Medicine" in the EMQ reference field (bare box)
--
-- Edits: EMQ scenario 2 reworded to "a stepwise programme of increasingly feared physical
-- activities"; SBA option E replaced with a closed, leading question so it is clearly not
-- consistent with motivational interviewing; "MI" abbreviation written out in full.
--
-- ON CONFLICT DO UPDATE so re-running applies any later edits. No new categories.

-- ===== New questions =====
insert into questions (id, type, data, status) values ('q_sba_motivational_interviewing_opioid_001', 'SBA', '{"dateAdded":"2026-10-02","rotationIndex":135,"question":"A patient with chronic low back pain and long-term opioid use tells you, \"I know I probably should cut down, but I''m just not ready yet.\" Which of the following responses best reflects the principles of motivational interviewing?","choices":["\"It sounds like part of you can see the benefits of cutting down, while another part isn''t quite ready yet. Can you tell me more about what''s holding you back?\"","\"That''s completely understandable. Change happens when you''re ready, so let''s just focus on your pain management for now and revisit this another time.\"","\"A lot of my patients feel that way initially, but once they see how much better they feel after reducing their dose, they usually wish they''d started sooner.\"","\"I hear you, but I do need to let you know that continuing at this dose long-term carries real risks, so it''s something we should seriously consider addressing soon.\"","\"Wouldn''t it be better to start cutting down now, while your pain is fairly stable?\""],"correct":0,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Option A explicitly <strong>reflects the patient&rsquo;s ambivalence</strong> back to them, naming both sides of it, and then uses an <strong>open-ended question</strong> to explore it further &mdash; combining reflective listening with evocation, the central engine of motivational interviewing.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Correct.</strong> Captures the patient&rsquo;s ambivalence accurately and non-judgementally, then invites further exploration with an open question, without steering the patient towards a particular conclusion.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> This sounds accepting and non-confrontational, but it <strong>avoids engaging with the ambivalence</strong> rather than exploring it. Motivational interviewing does not mean dropping the subject; it means exploring it skilfully. This response is passive rather than evocative.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> This may sound like gentle encouragement, but it <strong>installs the clinician&rsquo;s own conclusion</strong> (&ldquo;you&rsquo;ll feel better, you&rsquo;ll wish you&rsquo;d started sooner&rdquo;) rather than drawing out the patient&rsquo;s own reasons for change. That conflicts with the evocation principle of motivational interviewing, even though the tone is not aggressive.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> This begins with apparent empathy (&ldquo;I hear you&rdquo;) but pivots into <strong>clinician-delivered persuasion</strong> and an implicit push towards a timeline. It is a common blend of language that sounds like motivational interviewing with an underlying directive, advice-giving structure: it still supplies the argument for change rather than eliciting it from the patient.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> This is a <strong>closed, leading question</strong> &mdash; phrased as a question, but it presents the clinician&rsquo;s preferred answer and invites only &ldquo;yes&rdquo;. It ignores the patient&rsquo;s stated ambivalence and pushes towards a decision (the &ldquo;righting reflex&rdquo;), which tends to provoke sustain talk and resistance rather than drawing out the patient&rsquo;s own reasons for change.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Motivational Interviewing</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Definition</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">A <strong>collaborative, patient-centred communication style</strong> for strengthening a person&rsquo;s own motivation and commitment to change, by <strong>exploring and resolving ambivalence</strong>, rather than imposing change through direct persuasion, confrontation or authority.</p><div style=\"text-align:center;margin-top:12px\"><img src=\"images/motivational-interviewing-oars.svg\" alt=\"Motivational interviewing at a glance: the spirit (partnership, acceptance, compassion, evocation), the OARS core skills and the four processes (engaging, focusing, evoking, planning)\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Spirit of Motivational Interviewing (Underlying Philosophy)</div><table style=\"margin:0\"><tr><th>Element</th><th>Meaning</th></tr><tr><td><strong>Partnership</strong></td><td>Working collaboratively <strong>with</strong> the patient, who is the expert on their own life &mdash; collaboration rather than confrontation, not imposing the clinician&rsquo;s expertise</td></tr><tr><td><strong>Acceptance</strong></td><td>Respecting the patient&rsquo;s worth and <strong>autonomy</strong> (their right to make their own choices), with accurate empathy and affirmation of their strengths</td></tr><tr><td><strong>Compassion</strong></td><td>Actively prioritising the patient&rsquo;s welfare and best interests</td></tr><tr><td><strong>Evocation</strong></td><td>Drawing out the patient&rsquo;s <strong>own</strong> motivations and reasons for change, rather than installing motivation from outside</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Miller and Rollnick (3rd edition, 2013).</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Core Techniques &mdash; OARS</div><table style=\"margin:0\"><tr><th>Skill</th><th>What it involves</th></tr><tr><td><strong>O</strong>pen-ended questions</td><td>Encouraging elaboration rather than yes/no answers</td></tr><tr><td><strong>A</strong>ffirmations</td><td>Recognising patient strengths and efforts</td></tr><tr><td><strong>R</strong>eflective listening</td><td>Reflecting back what the patient has said, including their ambivalence, to deepen exploration</td></tr><tr><td><strong>S</strong>ummarising</td><td>Periodically pulling together what has been discussed</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">The Four Processes</div><table style=\"margin:0\"><tr><th>Process</th><th>Purpose</th></tr><tr><td><strong>Engaging</strong></td><td>Building a trusting, collaborative relationship</td></tr><tr><td><strong>Focusing</strong></td><td>Agreeing a direction or target for change</td></tr><tr><td><strong>Evoking</strong></td><td>Drawing out the patient&rsquo;s own reasons for change</td></tr><tr><td><strong>Planning</strong></td><td>Developing commitment and a concrete plan</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical Relevance in Pain Medicine</div><table style=\"margin:0\"><tr><th>Particularly useful for</th></tr><tr><td>Opioid tapering / dose-reduction discussions</td></tr><tr><td>Engagement with exercise and physiotherapy programmes</td></tr><tr><td>Smoking cessation and weight management</td></tr><tr><td>Engagement with multidisciplinary pain management programmes</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do update set data = excluded.data;
insert into questions (id, type, data, status) values ('q_emq_psychological_approaches_001', 'EMQ', '{"dateAdded":"2026-10-02","rotationIndex":136,"stem":"Psychological approaches in pain medicine","lead":"For each scenario below, select the single most appropriate approach from the options above. Each option may be used once, more than once, or not at all.","options":["Motivational interviewing","Cognitive behavioural therapy","Acceptance and commitment therapy","Biofeedback","Graded exposure","Shared decision-making","Psychoeducation","Behavioural activation"],"questions":[{"question":"A clinician reflects a patient''s ambivalence about reducing opioid use back to them, without directly advising a course of action.","correct":0,"explanation":"<strong>A. Motivational interviewing</strong> &mdash; reflecting ambivalence and exploring the patient&rsquo;s own reasons for and against change through open questions, without directing them towards a predetermined outcome, is the hallmark of motivational interviewing."},{"question":"A patient with chronic pain and significant fear of movement is guided through a stepwise programme of increasingly feared physical activities.","correct":4,"explanation":"<strong>E. Graded exposure</strong> &mdash; a structured, stepwise programme that starts with the least-feared movements and progresses gradually is the defining technique of graded exposure, used to address fear-avoidance and kinesiophobia in chronic pain."},{"question":"A clinician and patient discuss the risks and benefits of starting a spinal cord stimulator trial versus continuing conservative management.","correct":5,"explanation":"<strong>F. Shared decision-making</strong> &mdash; jointly weighing the risks and benefits of a specific treatment option, while incorporating the patient&rsquo;s values and preferences into a final collaborative decision, describes shared decision-making."},{"question":"A patient is taught to recognise and challenge unhelpful, catastrophic thoughts about their pain.","correct":1,"explanation":"<strong>B. Cognitive behavioural therapy</strong> &mdash; identifying and challenging unhelpful or catastrophic cognitions, alongside behavioural strategies, is the defining structure of cognitive behavioural therapy."},{"question":"A patient is given information explaining the neurophysiology of chronic pain and central sensitisation, to help them understand why their pain persists despite normal imaging.","correct":6,"explanation":"<strong>G. Psychoeducation</strong> &mdash; providing structured, factual information to help a patient understand the underlying mechanism of their condition (e.g. central sensitisation) is the definition of psychoeducation."}],"reference":"<div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Psychological Approaches in Pain Medicine</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Approaches at a Glance</div><table style=\"margin:0\"><tr><th>Approach</th><th>Key idea</th><th>Recognise it when&hellip;</th></tr><tr><td><strong>Motivational interviewing</strong></td><td>Collaborative style that explores and resolves ambivalence, evoking the patient&rsquo;s own reasons for change</td><td>The clinician reflects ambivalence and asks open questions without directing the outcome</td></tr><tr><td><strong>Cognitive behavioural therapy</strong></td><td>Thoughts, emotions and behaviours are linked; unhelpful patterns are changed with cognitive and behavioural strategies</td><td>Catastrophic or unhelpful thoughts are identified and challenged</td></tr><tr><td><strong>Acceptance and commitment therapy</strong></td><td>Psychological flexibility &mdash; accepting pain-related thoughts and sensations without struggle, clarifying values, and committing to value-driven action despite ongoing pain</td><td>The goal is living well with pain rather than reducing it</td></tr><tr><td><strong>Biofeedback</strong></td><td>Real-time physiological monitoring (e.g. EMG, skin temperature) and operant conditioning teach conscious control over processes contributing to pain/tension</td><td>Monitoring equipment gives the patient live feedback</td></tr><tr><td><strong>Graded exposure</strong></td><td>Stepwise exposure to feared movements, starting with the least feared and progressing gradually, to address fear-avoidance and kinesiophobia</td><td>There is fear of movement and a hierarchy of feared activities</td></tr><tr><td><strong>Shared decision-making</strong></td><td>Clinician and patient jointly weigh the risks and benefits of options, incorporating the patient&rsquo;s values and preferences into a collaborative decision</td><td>A specific treatment choice is being made together</td></tr><tr><td><strong>Psychoeducation</strong></td><td>Structured, factual information that helps the patient understand the mechanism of their condition (e.g. central sensitisation)</td><td>The patient is taught why pain persists despite normal imaging</td></tr><tr><td><strong>Behavioural activation</strong></td><td>Systematically increasing engagement in meaningful, rewarding activities to counteract avoidance and low mood</td><td>The focus is on rewarding activity and mood, not on a specific feared movement</td></tr></table></div></div>\n</div>"}'::jsonb, 'published')
  on conflict (id) do update set data = excluded.data;

